const all = $input.all();
const res = all.length ? all[0].json : {};
const els = Array.isArray(res.elements) ? res.elements : [];
const CITY = {'Riyadh':'Riyadh','Jeddah':'Jeddah','Dammam':'Dammam','Khobar':'Khobar','Al Khobar':'Khobar','Makkah':'Makkah','Mecca':'Makkah','Madinah':'Madinah','Medina':'Madinah'};
const SECTOR = {company:'IT & Services',it:'IT & Services',consulting:'IT & Services',estate_agent:'Real Estate',financial:'Finance & Insurance',insurance:'Finance & Insurance',logistics:'Logistics & Transport',travel_agent:'Hospitality & Tourism',educational_institution:'Education',construction_company:'Contracting & Construction'};
const out = [];
const seen = {};
for (const el of els) {
  const t = el.tags || {};
  const name = t['name:en'] || t.name;
  if (!name) continue;
  const phone = t.phone || t['contact:phone'] || '';
  if (!phone) continue;
  let website = t.website || t['contact:website'] || '';
  if (website && !/^https?:\/\//i.test(website)) website = 'https://' + website;
  const k = (String(name) + '|' + phone).toLowerCase();
  if (seen[k]) continue;
  seen[k] = 1;
  const office = t.office || '';
  let sector = SECTOR[office] || '';
  if (!sector) {
    if (t.shop) sector = 'Retail & Restaurants';
    else if (['restaurant','cafe','fast_food'].indexOf(t.amenity) > -1) sector = 'Retail & Restaurants';
    else if (t.healthcare || ['hospital','clinic','pharmacy'].indexOf(t.amenity) > -1) sector = 'Healthcare';
    else sector = 'Other';
  }
  const city = CITY[t['addr:city']] || 'Riyadh';
  const notes = 'OSM ' + el.type + '/' + el.id + (website ? ' | ' + website : '') + ' | ' + (office || t.shop || t.amenity || 'business');
  out.push({ json: { Name: String(name).slice(0, 200), Phone: phone, Sector: sector, City: city, Notes: notes } });
}
return out;
